settings.custom_css:
    selector .jet-slick-dots {
        width: 40%;
        justify-content: left;
        padding-left: 2rem;
        margin-top: -40px;
        position: relative;
}

@media (max-width: 767px) {
  selector .jet-slick-dots {
    width: 100%;
    justify-content: center;
    padding-left: 0;
    margin-top: -40px;
    display: flex; 
    position: relative;
  }
}

selector svg * {
    fill: var(--e-global-color-primary);
}

selector {
    z-index: 1;
    width: 62%;
    margin-inline: auto;
}
